package dev.underdeep.registry;

import dev.underdeep.Underdeep;
import net.minecraft.block.Block;
import net.minecraft.item.Item;
import net.minecraft.registry.RegistryKeys;
import net.minecraft.registry.tag.TagKey;
import net.minecraft.util.Identifier;

/** Underdeep block/item tags (contents generated by tools/assets/stage2_assets.py). */
public final class ModTags {
    /** Ordinary living-soil ground most land plants accept (dirt family, moss, glowing covers). */
    public static final TagKey<Block> PLANT_SOIL = block("plant_soil");
    /** Soils fungi grow on (fungal soils, mycelium, podzol, dirt, moss, rotting logs). */
    public static final TagKey<Block> FUNGAL_SOIL = block("fungal_soil");
    /** Hot volcanic ground (basalt, blackstone, magma, netherrack, soul soil, ember nylium). */
    public static final TagKey<Block> VOLCANIC_SOIL = block("volcanic_soil");
    /** Cold ground (snow block, packed/blue ice, powder snow, and plant soil). */
    public static final TagKey<Block> FROZEN_SOIL = block("frozen_soil");
    /** Mineral ground (stones, calcite, amethyst, luminite, stormstone, petrified wood). */
    public static final TagKey<Block> MINERAL_SOIL = block("mineral_soil");
    /** Wetland ground (mud, clay, muddy roots, plant soil). */
    public static final TagKey<Block> WET_SOIL = block("wet_soil");
    /** Lake and sea beds for submerged plants (sand, gravel, clay, mud, dirt, prismarine, stone). */
    public static final TagKey<Block> AQUATIC_BED = block("aquatic_bed");
    /** Blocks fungal soil may slowly convert (dirt, grass, coarse dirt, moss). Never farmland or paths. */
    public static final TagKey<Block> FUNGAL_CONVERTIBLE = block("fungal_convertible");
    /** Blocks shelf fungi attach to. */
    public static final TagKey<Block> SHELF_FUNGUS_HOSTS = block("shelf_fungus_hosts");
    /**
     * Player-made blocks near which natural spreading never places anything (planks, glass, chests,
     * redstone, farmland, paths, beds, rails, lights...). Protects builds and farms.
     */
    public static final TagKey<Block> GROWTH_BLOCKERS = block("growth_blockers");
    /** Host rock for Underdeep ores. */
    public static final TagKey<Block> ORE_HOSTS = block("ore_hosts");

    public static final TagKey<Item> HERBS = item("herbs");

    private ModTags() {
    }

    private static TagKey<Block> block(String path) {
        return TagKey.of(RegistryKeys.BLOCK, Identifier.of(Underdeep.MOD_ID, path));
    }

    private static TagKey<Item> item(String path) {
        return TagKey.of(RegistryKeys.ITEM, Identifier.of(Underdeep.MOD_ID, path));
    }
}
